def pisah_hitung_dan_lihat_stok(apps, schema_editor):
    """Orang yang menghitung stok (hitung buta) tidak boleh bisa melihat stok sistem.

    Akun yang punya keduanya kehilangan "lihat stok"; hitung stok dipertahankan.
    """
    for nama in ("HakAkun", "AkunKaryawan"):
        Model = apps.get_model("master", nama)
        kolom = "hak" if nama == "HakAkun" else "peran"
        for x in Model.objects.all():
            isi = list(getattr(x, kolom) or [])
            if "gudang_hitung" in isi and "ops_lihat_stok" in isi:
                isi.remove("ops_lihat_stok")
                setattr(x, kolom, isi)
                x.save(update_fields=[kolom])


